package com.meridian.student;
import com.meridian.dsa.StudentBST; import jakarta.annotation.PostConstruct; import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.*;
@Service public class StudentService {
 private final StudentRepository repo; private final StudentBST tree=new StudentBST(); private final List<Student> records=new ArrayList<>();
 public StudentService(StudentRepository repo){this.repo=repo;} @PostConstruct synchronized void load(){records.clear();records.addAll(repo.findAll());tree.rebuild(records);}
 public synchronized List<Student> list(String q,String department,String year,String status,String sort){Stream<Student>s=records.stream();if(q!=null&&!q.isBlank()){String x=q.toLowerCase();s=s.filter(v->v.getFullName().toLowerCase().contains(x)||v.getEmail().toLowerCase().contains(x)||v.getDepartment().toLowerCase().contains(x)||v.getCourse().toLowerCase().contains(x));}if(department!=null&&!department.isBlank())s=s.filter(v->v.getDepartment().equalsIgnoreCase(department));if(year!=null&&!year.isBlank())s=s.filter(v->v.getAcademicYear().equalsIgnoreCase(year));if(status!=null&&!status.isBlank())s=s.filter(v->v.getStatus().name().equalsIgnoreCase(status));Comparator<Student> c="cgpa".equals(sort)?Comparator.comparing(Student::getCgpa).reversed():"name".equals(sort)?Comparator.comparing(Student::getFullName,String.CASE_INSENSITIVE_ORDER):Comparator.comparing(Student::getId);return s.sorted(c).toList();}
 public synchronized Student get(long id){return records.stream().filter(s->s.getId()==id).findFirst().orElseThrow(()->new NoSuchElementException("Student not found"));}
 @Transactional public synchronized Student create(Student s){if(repo.existsByEmailIgnoreCase(s.getEmail()))throw new IllegalArgumentException("That email is already registered");Student saved=repo.save(s);tree.insert(saved);records.add(saved);return saved;}
 @Transactional public synchronized Student update(long id,Student in){Student old=get(id);repo.findByEmailIgnoreCase(in.getEmail()).filter(x->x.getId()!=id).ifPresent(x->{throw new IllegalArgumentException("That email is already registered");});in.setId(id);in.setCreatedAt(old.getCreatedAt());Student saved=repo.save(in);tree.insert(saved);records.set(records.indexOf(old),saved);return saved;}
 @Transactional public synchronized void delete(long id){Student s=get(id);repo.deleteById(id);tree.deleteById(id);records.remove(s);}
 public synchronized StudentBST.SearchResult bstSearch(long id){return tree.searchById(id);} public synchronized List<Student> snapshot(){return List.copyOf(records);}
}
